={{ (() => {
  const b = $json.body;
  const errors = {};
  if (!b || typeof b !== 'object' || Array.isArray(b)) {
    return { valid: false, errors: { body: 'Expected a JSON object' }, record: null };
  }
  const str = v => (v === undefined || v === null) ? '' : String(v).trim();
  const event = str(b.event);
  const reference = str(b.reference);
  const email = str(b.customer_email).toLowerCase();
  const amount = typeof b.amount === 'string' && b.amount.trim() !== '' ? Number(b.amount) : b.amount;

  if (!event) errors.event = 'Required string, e.g. "order.created"';
  if (!reference) errors.reference = 'Required string (your unique reference)';
  if (!email) errors.customer_email = 'Required';
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.customer_email = 'Not a valid email address';
  if (amount === undefined || amount === null || amount === '') errors.amount = 'Required number';
  else if (typeof amount !== 'number' || !Number.isFinite(amount)) errors.amount = 'Must be a number';
  else if (amount < 0) errors.amount = 'Must be >= 0';

  return {
    valid: Object.keys(errors).length === 0,
    errors,
    record: {
      event, reference, customer_email: email,
      amount: typeof amount === 'number' ? amount : null,
      currency: (str(b.currency) || 'IDR').toUpperCase().slice(0, 3),
      notes: str(b.notes).slice(0, 1000)
    }
  };
})() }}

={{ (() => {
  let p = {};
  try { p = JSON.parse($json.payload_json || '{}') ?? {}; } catch (e) { p = {}; }
  const amount = typeof p.amount === 'string' && p.amount.trim() !== '' ? Number(p.amount) : p.amount;
  return {
    request_id: $json.request_id,
    received_at: $json.received_at,
    event: String(p.event ?? '').trim(),
    reference: String(p.reference ?? '').trim(),
    customer_email: String(p.customer_email ?? '').trim().toLowerCase(),
    amount: typeof amount === 'number' && Number.isFinite(amount) ? amount : null,
    currency: (String(p.currency ?? '').trim() || 'IDR').toUpperCase().slice(0, 3),
    notes: String(p.notes ?? '').trim().slice(0, 1000)
  };
})() }}

={{ (() => {
  const t = $('On Workflow Error').first().json;
  const msg = t.execution?.error?.message ?? t.trigger?.error?.message ?? '';
  if (msg.includes('[CRITICAL]')) return 'CRITICAL';
  if (msg.includes('[WARNING]')) return 'WARNING';
  return 'ERROR';
})() }}
